class RandomizedCollection {
    private final java.util.ArrayList<Integer> values = new java.util.ArrayList<>();
    private final java.util.Map<Integer, java.util.LinkedHashSet<Integer>> indexes = new java.util.HashMap<>();
    private final java.util.Random random = new java.util.Random();

    public RandomizedCollection() {
    }

    public boolean insert(int val) {
        java.util.LinkedHashSet<Integer> set = indexes.computeIfAbsent(val, key -> new java.util.LinkedHashSet<>());
        boolean isNew = set.isEmpty();
        set.add(values.size());
        values.add(val);
        return isNew;
    }

    public boolean remove(int val) {
        java.util.LinkedHashSet<Integer> set = indexes.get(val);
        if (set == null || set.isEmpty()) {
            return false;
        }
        int removeIndex = set.iterator().next();
        set.remove(removeIndex);
        int lastIndex = values.size() - 1;
        int lastValue = values.get(lastIndex);
        if (removeIndex != lastIndex) {
            values.set(removeIndex, lastValue);
            java.util.LinkedHashSet<Integer> lastSet = indexes.get(lastValue);
            lastSet.remove(lastIndex);
            lastSet.add(removeIndex);
        }
        values.remove(lastIndex);
        if (set.isEmpty()) {
            indexes.remove(val);
        }
        return true;
