        if (set == null || set.isEmpty()) {
            return false;
        }
        int removeIndex = set.iterator().next();
        set.remove(removeIndex);
        int lastIndex = size - 1;
        int lastValue = values[lastIndex];
        if (removeIndex != lastIndex) {
            values[removeIndex] = lastValue;
            java.util.HashSet<Integer> lastSet = indexes.get(lastValue);
            lastSet.remove(lastIndex);
            lastSet.add(removeIndex);
        }
        size--;
        if (set.isEmpty()) {
            indexes.remove(val);
        }
        return true;
    }

    public int getRandom() {
