class RandomizedCollection {
    private static class Entry {
        int value;
        int index;

        Entry(int value, int index) {
            this.value = value;
            this.index = index;
        }
    }

    private final java.util.ArrayList<Entry> dense = new java.util.ArrayList<>();
    private final java.util.Map<Integer, java.util.HashSet<Entry>> buckets = new java.util.HashMap<>();
    private final java.util.Random random = new java.util.Random();

    public RandomizedCollection() {
    }

    public boolean insert(int val) {
        java.util.HashSet<Entry> bucket = buckets.computeIfAbsent(val, key -> new java.util.HashSet<>());
        boolean isNew = bucket.isEmpty();
        Entry entry = new Entry(val, dense.size());
        dense.add(entry);
        bucket.add(entry);
        return isNew;
    }

    public boolean remove(int val) {
        java.util.HashSet<Entry> bucket = buckets.get(val);
        if (bucket == null || bucket.isEmpty()) {
            return false;
        }
        Entry target = bucket.iterator().next();
        bucket.remove(target);
        if (bucket.isEmpty()) {
            buckets.remove(val);
        }
        Entry last = dense.remove(dense.size() - 1);
        if (target != last) {
            dense.set(target.index, last);
            last.index = target.index;
        }
        return true;
    }

    public int getRandom() {
        return dense.get(random.nextInt(dense.size())).value;
    }
}

class RandomizedCollection {
    private static class IndexBag {
        private final java.util.ArrayList<Integer> indexes = new java.util.ArrayList<>();
        private final java.util.Map<Integer, Integer> positions = new java.util.HashMap<>();

        boolean isEmpty() {
            return indexes.isEmpty();
        }

        int any() {
            return indexes.get(indexes.size() - 1);
        }

        void add(int index) {
            positions.put(index, indexes.size());
            indexes.add(index);
        }

        void remove(int index) {
            int position = positions.remove(index);
            int lastIndex = indexes.remove(indexes.size() - 1);
            if (position < indexes.size()) {
                indexes.set(position, lastIndex);
                positions.put(lastIndex, position);
            }
        }
    }

    private final java.util.ArrayList<Integer> values = new java.util.ArrayList<>();
    private final java.util.Map<Integer, IndexBag> bags = new java.util.HashMap<>();
    private final java.util.Random random = new java.util.Random();

    public RandomizedCollection() {
    }

    public boolean insert(int val) {
        IndexBag bag = bags.computeIfAbsent(val, key -> new IndexBag());
        boolean isNew = bag.isEmpty();
        bag.add(values.size());
        values.add(val);
        return isNew;
    }

    public boolean remove(int val) {
        IndexBag bag = bags.get(val);
        if (bag == null || bag.isEmpty()) {
            return false;
        }
        int removeIndex = bag.any();
        bag.remove(removeIndex);
        int lastIndex = values.size() - 1;
        int lastValue = values.get(lastIndex);
        if (removeIndex != lastIndex) {
            values.set(removeIndex, lastValue);
            IndexBag lastBag = bags.get(lastValue);
            lastBag.remove(lastIndex);
            lastBag.add(removeIndex);
        }
        values.remove(lastIndex);
        if (bag.isEmpty()) {
            bags.remove(val);
        }
        return true;
    }

    public int getRandom() {
        return values.get(random.nextInt(values.size()));
    }
